def find_min_atoms(n, m, subsets):
    from collections import defaultdict

    # Create a graph where each node represents an element in X
    # and an edge between two nodes if they are in the same subset
    graph = defaultdict(list)
    for subset in subsets:
        for i in range(1, len(subset)):
            for j in range(i):
                graph[subset[i]].append(subset[j])
                graph[subset[j]].append(subset[i])

    # Colors to mark the atoms
    color = [-1] * n

    def dfs(node, c):
        color[node] = c
        for neighbor in graph[node]:
            if color[neighbor] == -1:
                dfs(neighbor, c)

    # Assign colors to each node
    num_colors = 0
    for i in range(n):
        if color[i] == -1:
            dfs(i, num_colors)
            num_colors += 1

    return num_colors

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        m = int(data[index + 1])
        index += 2
        subsets = []
        for _ in range(m):
            vi = int(data[index])
            subset = list(map(int, data[index + 1:index + vi + 1]))
            index += vi + 1
            subsets.append(subset)
        results.append(find_min_atoms(n, m, subsets))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
